# Manual analysis of minimal edits
def find_minimal_edit(s_in, s_out):
    """Helper to find minimal edit"""
    # Find first difference
    min_len = min(len(s_in), len(s_out))

    # Find insertion/deletion points
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if this is insertion/deletion by looking ahead
            if len(s_in) < len(s_out):
                # Insertion detected
                return (s_in[i-1:i], s_out[i:i+1], i-1) if i > 0 else (s_in[i:i+1], s_out[i:i+1], i)
            elif len(s_in) > len(s_out):
                # Deletion detected
                return (s_in[i:i+1], s_out[i:i], i)
            else:
                # Substitution
                return (s_in[i:i+1], s_out[i:i+1], i)

    # If we reach here, one string is prefix of other
    if len(s_in) < len(s_out):
        return (s_in[-1:], s_out[-1:], len(s_in)-1) if len(s_in) > 0 else (s_in, s_out[-1:], 0)
    elif len(s_in) > len(s_out):
        return (s_in[-1:], "", len(s_in)-1)
    else:
        return ("", "", -1)  # No difference

inputs = ['vijdve', 'duac', 'iv', 'xagjd', 'fy']
outputs = ['xcfeyjdxe', 'duakfk', 'cfeyx', 'xagjd', 'fy']

print("Analyzing minimal edits:")
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        old_sub, new_sub, pos = find_minimal_edit(inputs[i], outputs[i])
        print(f"  {i}: '{inputs[i]}' -> '{outputs[i]}' | Edit: '{old_sub}' -> '{new_sub}' at pos {pos}")

